insert into public.questions (id, subject_id, number, block, statement, hints, scaffold) values
  ('2416a286-6eb6-5ef5-b584-903e5ef94bcf'::uuid, (select id from public.subjects where slug = 'ingles'), 1, 'Bloco 1 — Skimming and Scanning', 'Explique, com suas próprias palavras, a diferença entre Skimming e Scanning. Apresente uma situação em que cada técnica seria mais adequada.', '[]'::jsonb, null),
  ('6db43f8c-02f4-5b17-9c4b-98859b6cc086'::uuid, (select id from public.subjects where slug = 'ingles'), 2, 'Bloco 1 — Skimming and Scanning', 'Leia: “Lucas wakes up at 6:30 a.m. He has breakfast, goes to school at 7:15 a.m. and returns home at 12:30 p.m. In the afternoon, he plays soccer with his friends.” Utilizando Skimming, identifique o assunto principal do texto.', '[]'::jsonb, null),
  ('7cdb5a2b-5f60-576a-815d-9957481623c5'::uuid, (select id from public.subjects where slug = 'ingles'), 3, 'Bloco 1 — Skimming and Scanning', 'Utilizando Scanning, responda: (a) What time does Lucas wake up? (b) What time does he go to school? (c) What does he do in the afternoon?', '[]'::jsonb, null),
  ('d3136e6d-5971-50c1-9322-c818fbb75806'::uuid, (select id from public.subjects where slug = 'ingles'), 4, 'Bloco 1 — Skimming and Scanning', 'Imagine que você precisa encontrar rapidamente a data de publicação de uma notícia em uma página com muitos parágrafos. Qual técnica utilizaria? Justifique.', '[]'::jsonb, null),
  ('dbd4eeca-e226-571a-8024-e35aebd699c9'::uuid, (select id from public.subjects where slug = 'ingles'), 5, 'Bloco 1 — Skimming and Scanning', 'Um estudante precisa descobrir o assunto geral de um texto antes de começar uma leitura detalhada. Qual técnica deverá utilizar e por quê?', '[]'::jsonb, null),
  ('1ad47d63-a371-5a3d-9cf6-40fdec92c33f'::uuid, (select id from public.subjects where slug = 'ingles'), 6, 'Bloco 2 — Fact or Fake e Reliable Sources', 'Explique o significado das expressões Fact e Fake News. Qual é a principal diferença entre elas?', '[]'::jsonb, null),
  ('0c7e7e77-179e-5acf-9b19-eb08b76f5765'::uuid, (select id from public.subjects where slug = 'ingles'), 7, 'Bloco 2 — Fact or Fake e Reliable Sources', 'Você recebeu pelo WhatsApp uma notícia afirmando que todas as escolas estarão fechadas amanhã. A mensagem não apresenta autor, fonte ou link oficial. Quais três atitudes deve tomar antes de acreditar nela?', '[]'::jsonb, null),
  ('90e3a78d-ef30-5a88-981a-19283620f8b9'::uuid, (select id from public.subjects where slug = 'ingles'), 8, 'Bloco 2 — Fact or Fake e Reliable Sources', 'Cite quatro características que ajudam a identificar uma fonte de informação confiável.', '[]'::jsonb, null),
  ('eccb06c2-6db4-5e93-801d-d51ff028240f'::uuid, (select id from public.subjects where slug = 'ingles'), 9, 'Bloco 2 — Fact or Fake e Reliable Sources', 'Uma notícia apresenta um título alarmante, mas seu conteúdo não apresenta provas. Por que não devemos compartilhar essa informação imediatamente?', '[]'::jsonb, null),
  ('7fa2ddba-6c3b-5c59-a7ef-c2b69a4e0752'::uuid, (select id from public.subjects where slug = 'ingles'), 10, 'Bloco 2 — Fact or Fake e Reliable Sources', 'Explique por que é importante comparar uma informação em diferentes fontes antes de considerá-la verdadeira.', '[]'::jsonb, null),
  ('306a1195-ab6c-503e-b6ca-4f650060da86'::uuid, (select id from public.subjects where slug = 'ingles'), 11, 'Bloco 3 — Bullying e Cyberbullying', 'Explique a diferença entre Bullying e Cyberbullying. Apresente um exemplo de cada um.', '[]'::jsonb, null),
  ('be311931-14c7-578c-a147-6ad17793b630'::uuid, (select id from public.subjects where slug = 'ingles'), 12, 'Bloco 3 — Bullying e Cyberbullying', 'Um aluno publica uma fotografia de um colega em uma rede social, acompanhada de comentários ofensivos. Identifique o problema e explique por que essa atitude é prejudicial.', '[]'::jsonb, null),
  ('30e1ade5-aa75-520a-8004-02273ff4784c'::uuid, (select id from public.subjects where slug = 'ingles'), 13, 'Bloco 3 — Bullying e Cyberbullying', 'Cite três consequências que o bullying pode provocar na vida de uma vítima.', '[]'::jsonb, null),
  ('b4d29c15-0e76-5db6-8ee8-36df10908934'::uuid, (select id from public.subjects where slug = 'ingles'), 14, 'Bloco 3 — Bullying e Cyberbullying', 'Um estudante presencia um colega sendo humilhado em um grupo de mensagens. Qual seria a atitude mais responsável? Explique.', '[]'::jsonb, null),
  ('a5652962-79c5-5484-80fa-5af0c77a16ac'::uuid, (select id from public.subjects where slug = 'ingles'), 15, 'Bloco 3 — Bullying e Cyberbullying', 'Por que o anonimato na internet não torna uma pessoa livre de responsabilidade pelas próprias atitudes?', '[]'::jsonb, null),
  ('5e7f52c1-382e-560f-87b0-d2ff806b1189'::uuid, (select id from public.subjects where slug = 'ingles'), 16, 'Bloco 4 — Rules e Paragraph', 'Explique a importância das regras na família, na escola e na sociedade. Apresente um exemplo de cada ambiente.', '[]'::jsonb, null),
  ('a49c74ef-47f1-5cd3-8324-0fa9e3d3a81b'::uuid, (select id from public.subjects where slug = 'ingles'), 17, 'Bloco 4 — Rules e Paragraph', 'Traduza para o português e explique o significado: (a) Students must respect their teachers. (b) We must follow school rules. (c) People should respect each other.', '[]'::jsonb, null),
  ('0a586599-545b-53da-84e9-9aacd97d4f68'::uuid, (select id from public.subjects where slug = 'ingles'), 18, 'Bloco 4 — Rules e Paragraph', 'Explique a diferença entre Audience e Purpose na construção de um parágrafo.', '[]'::jsonb, null),
  ('eaaaf110-7094-5af0-b86f-126dd3271ddf'::uuid, (select id from public.subjects where slug = 'ingles'), 19, 'Bloco 4 — Rules e Paragraph', 'Imagine que você precisa escrever um parágrafo para convencer seus colegas a preservarem o ambiente escolar. Identifique: Audience; Purpose; Main idea; Two supporting arguments.', '[]'::jsonb, null),
  ('57859100-868e-5e26-8d83-4177ef70499f'::uuid, (select id from public.subjects where slug = 'ingles'), 20, 'Bloco 4 — Rules e Paragraph', 'Produza um parágrafo em inglês, com pelo menos cinco frases, sobre a importância do respeito na escola. O texto deverá apresentar uma ideia principal, argumentos de apoio e uma conclusão.', '[]'::jsonb, null),
  ('43937540-9a2a-5532-abfa-66c160e8cc8f'::uuid, (select id from public.subjects where slug = 'portugues'), 1, 'Bloco 1 — Figuras de linguagem', 'Explique o que são figuras de linguagem e qual é sua importância na construção de textos.', '[]'::jsonb, null),
  ('fcdd5b0e-0370-5157-a699-aca1799d578b'::uuid, (select id from public.subjects where slug = 'portugues'), 2, 'Bloco 1 — Figuras de linguagem', 'Identifique a figura de linguagem em “Meu coração é um deserto sem você”. Explique o efeito de sentido.', '[]'::jsonb, null),
  ('ba971e6a-9c84-5ca1-9202-8cda12b2e0bb'::uuid, (select id from public.subjects where slug = 'portugues'), 3, 'Bloco 1 — Figuras de linguagem', 'Identifique e explique a figura de linguagem: “Seus olhos brilhavam como estrelas”.', '[]'::jsonb, null),
  ('57b38e0e-5933-510d-b92f-391a339d480c'::uuid, (select id from public.subjects where slug = 'portugues'), 4, 'Bloco 1 — Figuras de linguagem', 'Em “O vento sussurrava entre as árvores”, qual figura foi utilizada? Justifique.', '[]'::jsonb, null),
  ('ff8dbc81-bbfd-56ba-aa6a-07d5d96675a6'::uuid, (select id from public.subjects where slug = 'portugues'), 5, 'Bloco 1 — Figuras de linguagem', 'Explique a diferença entre comparação e metáfora. Crie um exemplo de cada uma.', '[]'::jsonb, null),
  ('5087c059-b125-500e-bdaa-a174e5adc648'::uuid, (select id from public.subjects where slug = 'portugues'), 6, 'Bloco 1 — Figuras de linguagem', 'Identifique a figura em “Já te falei isso um milhão de vezes!”. Explique.', '[]'::jsonb, null),
  ('dd41b4aa-f8fc-5037-95d3-799706cf7c2c'::uuid, (select id from public.subjects where slug = 'portugues'), 7, 'Bloco 1 — Figuras de linguagem', 'Analise “Estou morrendo de fome!”. Identifique a figura e explique o significado real.', '[]'::jsonb, null),
  ('9627c8af-74bf-556d-b92d-fc5f2281f68b'::uuid, (select id from public.subjects where slug = 'portugues'), 8, 'Bloco 1 — Figuras de linguagem', 'Em “O doce som da sua voz”, existe combinação de sensações. Identifique a figura e explique.', '[]'::jsonb, null),
  ('c4ba002d-ba64-5e7d-a417-062c9ed84d38'::uuid, (select id from public.subjects where slug = 'portugues'), 9, 'Bloco 1 — Figuras de linguagem', 'Crie quatro frases diferentes, utilizando uma metáfora, uma comparação, uma personificação e uma hipérbole.', '[]'::jsonb, null),
  ('4b943610-4d73-5c0b-bed5-131686c08975'::uuid, (select id from public.subjects where slug = 'portugues'), 10, 'Bloco 1 — Figuras de linguagem', 'Leia “A cidade acordou triste naquela manhã”. Identifique a figura e explique como modifica a interpretação.', '[]'::jsonb, null),
  ('5efe8bc1-6a4d-5b12-b8cd-eded342e2201'::uuid, (select id from public.subjects where slug = 'portugues'), 11, 'Bloco 2 — Advérbios', 'Explique o que é um advérbio e qual é sua função na oração.', '[]'::jsonb, null),
  ('097d42cd-4961-5c45-bc70-673db71c327e'::uuid, (select id from public.subjects where slug = 'portugues'), 12, 'Bloco 2 — Advérbios', 'Identifique os advérbios e classifique-os: (a) João chegou cedo. (b) Maria mora longe. (c) Talvez chova amanhã. (d) Ele falou calmamente. (e) Não quero sair.', '[]'::jsonb, null),
  ('4182a82b-fbf8-52b7-b03f-45c54bdf33bc'::uuid, (select id from public.subjects where slug = 'portugues'), 13, 'Bloco 2 — Advérbios', 'Classifique os advérbios destacados: (a) Ela chegou ontem. (b) O menino correu rapidamente. (c) O livro está aqui. (d) Talvez ele participe. (e) Ela é muito inteligente.', '[]'::jsonb, null),
  ('49c43f36-40bb-508c-a575-dbebe2bc5768'::uuid, (select id from public.subjects where slug = 'portugues'), 14, 'Bloco 2 — Advérbios', 'Explique a diferença entre advérbio de tempo, lugar, modo e intensidade. Apresente dois exemplos de cada.', '[]'::jsonb, null),
  ('44ba059b-195a-5635-97fd-204bd7563122'::uuid, (select id from public.subjects where slug = 'portugues'), 15, 'Bloco 2 — Advérbios', 'Em “O aluno estudou bastante para a avaliação”, identifique o advérbio e explique a circunstância.', '[]'::jsonb, null),
  ('d965d674-8dcb-5ee8-a00b-8e4c729d7938'::uuid, (select id from public.subjects where slug = 'portugues'), 16, 'Bloco 2 — Advérbios', 'Substitua as expressões por advérbios equivalentes: (a) com educação; (b) com rapidez; (c) com atenção; (d) de maneira clara.', '[]'::jsonb, null),
  ('ba2e1e67-1503-5fab-b0a7-235d93d1d111'::uuid, (select id from public.subjects where slug = 'portugues'), 17, 'Bloco 2 — Advérbios', 'Explique por que “muito” exerce funções diferentes: (a) Ela é muito inteligente. (b) Existem muitos livros na biblioteca.', '[]'::jsonb, null),
  ('46cd37f2-ee03-55a5-8ff0-f8c236862551'::uuid, (select id from public.subjects where slug = 'portugues'), 18, 'Bloco 2 — Advérbios', 'Crie cinco frases contendo advérbios de circunstâncias diferentes. Identifique e classifique cada um.', '[]'::jsonb, null),
  ('aa26aff3-56dc-5aa3-bd8f-a4a866af2923'::uuid, (select id from public.subjects where slug = 'portugues'), 19, 'Bloco 3 — Interpretação e aplicação', 'Leia: “Ontem, Pedro chegou muito cedo à escola. Rapidamente, organizou seus materiais e começou a estudar. Talvez conseguisse terminar todas as atividades antes do intervalo.” Identifique e classifique todos os advérbios.', '[]'::jsonb, null),
  ('27a0dbd8-c520-5125-95a4-11047ba8e1ef'::uuid, (select id from public.subjects where slug = 'portugues'), 20, 'Bloco 3 — Interpretação e aplicação', 'Produza um pequeno parágrafo sobre sua rotina de estudos utilizando pelo menos quatro advérbios diferentes e duas figuras de linguagem. Ao final, identifique os elementos utilizados.', '[]'::jsonb, null),
  ('8609f171-325f-5e66-9f7f-b19bd4c680f6'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 1, 'Bloco 1 — Razão', 'Explique o que é razão entre duas grandezas e como ela pode ser representada matematicamente.', '[]'::jsonb, null),
  ('7d5bb093-01a5-5ac0-a4b3-6218f34784f2'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 2, 'Bloco 1 — Razão', 'Uma sala possui 12 meninas e 18 meninos. Determine: (a) razão meninas:meninos; (b) meninos:meninas; (c) meninas:total.', '[]'::jsonb, null),
  ('2b4bea3a-91da-5c29-8ac0-3e9f8f7e79e2'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 3, 'Bloco 1 — Razão', 'Simplifique: (a) 12:18; (b) 20:35; (c) 45:60.', '[]'::jsonb, null),
  ('7a80ba90-353c-5a5f-b753-e7f7482de2b0'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 4, 'Bloco 1 — Razão', 'Uma receita utiliza 2 xícaras de leite para cada 3 de farinha. Qual a razão leite:farinha? Se forem utilizadas 9 xícaras de farinha, quantas de leite serão necessárias?', '[]'::jsonb, null),
  ('d058797d-ba3f-5bfa-8952-cef554cd4433'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 5, 'Bloco 2 — Proporção', 'Explique o que é uma proporção e como verificar se duas razões são equivalentes.', '[]'::jsonb, null),
  ('4bbc3376-7f15-5697-a69d-f70281c45ead'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 6, 'Bloco 2 — Proporção', 'Verifique se 2/3 e 8/12 formam uma proporção. Demonstre.', '[]'::jsonb, null),
  ('8f6c58ab-c85a-579e-899b-44bc1d9783dd'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 7, 'Bloco 2 — Proporção', 'Determine x: 3/5 = x/20.', '[]'::jsonb, null),
  ('4f40c6d6-d9ad-56f4-b6b0-cd223ec3bd61'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 8, 'Bloco 2 — Proporção', 'Uma fotografia mede 10 cm de largura e 15 cm de altura. Se ampliada proporcionalmente para 30 cm de largura, qual será a nova altura?', '[]'::jsonb, null),
  ('20a9c176-c553-50ec-a29e-3d8c054a1cfc'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 9, 'Bloco 3 — Grandezas proporcionais', 'Explique a diferença entre grandezas diretamente e inversamente proporcionais.', '[]'::jsonb, null),
  ('331c5bf7-ecf8-5db0-a52c-797ddc0245b5'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 10, 'Bloco 3 — Grandezas proporcionais', 'Se 3 cadernos custam R$ 24,00, quanto custarão 7 pelo mesmo preço unitário?', '[]'::jsonb, null),
  ('576642bb-e03a-5b68-a224-3f60665b091d'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 11, 'Bloco 3 — Grandezas proporcionais', 'Um automóvel percorre 120 km em 2 horas, com velocidade constante. Quantos quilômetros percorrerá em 5 horas?', '[]'::jsonb, null),
  ('021b10d4-8e52-5811-8264-b41d0a3a2412'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 12, 'Bloco 3 — Grandezas proporcionais', 'Quatro trabalhadores realizam um serviço em 12 dias. Em quantos dias 8 trabalhadores realizariam o mesmo serviço, com produtividade igual?', '[]'::jsonb, null),
  ('2c635c27-6fe8-5937-80a7-ea0ca37cf6cc'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 13, 'Bloco 4 — Circunferências', 'Explique a diferença entre círculo e circunferência.', '[]'::jsonb, null),
  ('0aafbf89-1fbe-5659-a3d6-2684285c8a12'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 14, 'Bloco 4 — Circunferências', 'Uma circunferência possui raio de 5 cm. Determine diâmetro e comprimento, usando π = 3,14.', '[]'::jsonb, null),
  ('6f67539d-8f7d-5767-8d5c-740a8064d915'::uuid, (select id from public.subjects where slug = 'matematica-dia-1'), 15, 'Bloco 4 — Circunferências', 'Uma roda possui diâmetro de 70 cm. Quantos centímetros percorre em uma volta completa? Use π = 3,14.', '[]'::jsonb, null),
  ('14192b15-db75-5a99-9cde-91ecae94a59f'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 1, 'Bloco 1 — Razão e proporção', 'Em uma escola existem 240 estudantes, dos quais 144 são meninas. Determine a razão meninas:meninos na forma simplificada.', '[]'::jsonb, null),
  ('0f75e41c-bec6-5d92-8e35-13bd605cdb39'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 2, 'Bloco 1 — Razão e proporção', 'Uma fábrica produz 180 peças em 3 horas. Mantendo o ritmo, quantas produzirá em 8 horas?', '[]'::jsonb, null),
  ('7879d467-b3b4-55f0-9b9d-ef9763fb2c47'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 3, 'Bloco 1 — Razão e proporção', 'Em um mapa, 2 cm representam 50 km. Qual distância real será representada por 7,5 cm?', '[]'::jsonb, null),
  ('75ca4927-6376-52a7-b416-04fe68e70f2d'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 4, 'Bloco 1 — Razão e proporção', 'Uma mistura utiliza 4 partes de tinta azul para 3 de tinta branca. Quantas partes de cada serão necessárias para 35 partes?', '[]'::jsonb, null),
  ('48d7fd7f-49e5-55d9-8b30-d4917f1e5338'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 5, 'Bloco 1 — Razão e proporção', 'Determine x: 7/9 = x/45.', '[]'::jsonb, null),
  ('9b3dcc24-fa6b-5a94-bdd8-e3612d66e118'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 6, 'Bloco 1 — Razão e proporção', 'Um carro percorre 180 km com 15 litros. Quantos litros para 300 km, com o mesmo consumo?', '[]'::jsonb, null),
  ('ab3bc775-354a-59a2-9894-4f1a75e80269'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 7, 'Bloco 1 — Razão e proporção', 'Um grupo tem 8 meninos e 12 meninas. Mantida a proporção, total de 50 integrantes. Quantos meninos e meninas?', '[]'::jsonb, null),
  ('137727da-0aa7-55a5-b927-ef7abe2259d8'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 8, 'Bloco 1 — Razão e proporção', 'Uma receita para 4 pessoas usa 300 g de arroz. Quanto para 10 pessoas?', '[]'::jsonb, null),
  ('134e7532-fece-5e46-8b54-e6db0be4bf4d'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 9, 'Bloco 2 — Grandezas diretamente proporcionais', 'Uma máquina produz 240 peças em 4 horas. Quantas produzirá em 9 horas?', '[]'::jsonb, null),
  ('56367c5e-6e28-5dac-bb83-67d7d1ed0da1'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 10, 'Bloco 2 — Grandezas diretamente proporcionais', 'Cinco ingressos custam R$ 175,00. Quanto custam 12 pelo mesmo preço unitário?', '[]'::jsonb, null),
  ('f0af3662-2093-5078-8578-7736b872eff5'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 11, 'Bloco 2 — Grandezas diretamente proporcionais', 'Um trabalhador recebe R$ 180,00 por 6 horas. Quanto receberá por 9 horas, proporcionalmente?', '[]'::jsonb, null),
  ('e353de37-c7a1-526a-807b-4d290d0407cd'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 12, 'Bloco 2 — Grandezas diretamente proporcionais', 'Uma torneira despeja 18 litros em 3 minutos. Quantos litros em 11 minutos?', '[]'::jsonb, null),
  ('f8599e9b-a147-5e94-a5b8-142491efe2e9'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 13, 'Bloco 3 — Grandezas inversamente proporcionais', 'Seis funcionários concluem uma tarefa em 15 dias. Em quantos dias 10 funcionários fariam a mesma tarefa, com produtividade igual?', '[]'::jsonb, null),
  ('52bd43f2-6dd0-551d-842d-4808c085bf0b'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 14, 'Bloco 3 — Grandezas inversamente proporcionais', 'Um trajeto é percorrido em 4 horas a 60 km/h. Quanto tempo levaria a 80 km/h, na mesma distância?', '[]'::jsonb, null),
  ('b2be3f43-986c-564c-8018-e75ec5bb9800'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 15, 'Bloco 3 — Grandezas inversamente proporcionais', 'Doze pessoas têm alimentos para 20 dias. Se forem 15 pessoas, por quantos dias durarão, com consumo igual?', '[]'::jsonb, null),
  ('4d5b218b-8070-5c24-a17e-dc55ced2cf24'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 16, 'Bloco 3 — Grandezas inversamente proporcionais', 'Uma piscina é esvaziada por 3 bombas iguais em 12 horas. Quanto tempo com 4 bombas iguais?', '[]'::jsonb, null),
  ('65a4d699-67af-57ae-9ccc-fc7f85f5b8f5'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 17, 'Bloco 3 — Grandezas inversamente proporcionais', 'Explique por que aumentar o número de trabalhadores pode diminuir o tempo de uma tarefa, sem diminuir a quantidade de trabalho.', '[]'::jsonb, null),
  ('d928ddae-26bc-5142-bc2a-85112c7cd205'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 18, 'Bloco 4 — Circunferências', 'Explique a relação matemática entre raio e diâmetro.', '[]'::jsonb, null),
  ('5dfefc27-447e-5438-aae8-9476bbab71ff'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 19, 'Bloco 4 — Circunferências', 'Uma circunferência possui raio de 8 cm. Calcule diâmetro e comprimento, usando π = 3,14.', '[]'::jsonb, null),
  ('d37551d9-0ef9-5efe-9bea-46c667518211'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 20, 'Bloco 4 — Circunferências', 'Uma circunferência possui diâmetro de 20 cm. Determine seu comprimento.', '[]'::jsonb, null),
  ('004bd5b0-5e4a-5e73-bcb4-76b6523990d9'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 21, 'Bloco 4 — Circunferências', 'Uma roda tem raio de 35 cm. Qual distância percorre em 10 voltas? Use π = 3,14.', '[]'::jsonb, null),
  ('90d0372a-4bf6-59bc-b202-bdf34c7fab2d'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 22, 'Bloco 4 — Circunferências', 'O comprimento de uma circunferência é 62,8 cm. Determine seu raio, usando π = 3,14.', '[]'::jsonb, null),
  ('f92ea17e-4196-52cd-a561-62715a37d03d'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 23, 'Bloco 4 — Circunferências', 'Duas circunferências têm raios de 4 cm e 8 cm. Compare seus comprimentos.', '[]'::jsonb, null),
  ('a7049f80-0c1e-5cd4-826c-e66e1e5d950d'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 24, 'Bloco 4 — Circunferências', 'Uma pista circular possui diâmetro de 100 m. Quantos metros uma pessoa percorre em 3 voltas?', '[]'::jsonb, null),
  ('82863e6f-0399-52a1-83e7-098e2c27282c'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 25, 'Bloco 5 — Problemas integradores e raciocínio', 'Uma fábrica produz 600 peças em 5 horas utilizando 4 máquinas iguais. Quantas peças serão produzidas em 8 horas com 6 máquinas, mantendo a produtividade?', '[]'::jsonb, null),
  ('dc2ad9d3-d4e4-5604-ba4c-17cb61d51758'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 26, 'Bloco 5 — Problemas integradores e raciocínio', 'Uma viagem de 240 km é feita em 4 horas. Se a velocidade média aumentar de 60 km/h para 80 km/h, quanto tempo será economizado?', '[]'::jsonb, null),
  ('682fddee-877c-5003-bfd2-a9b390e3738a'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 27, 'Bloco 5 — Problemas integradores e raciocínio', 'Uma receita usa 500 g de farinha para 20 biscoitos. Quantos gramas para 70 biscoitos? E para 100?', '[]'::jsonb, null),
  ('f314cded-e143-5819-8205-ca3248f023c1'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 28, 'Bloco 5 — Problemas integradores e raciocínio', 'Uma roda percorre 188,4 m após 30 voltas. Determine o comprimento da circunferência e o raio. Use π = 3,14.', '[]'::jsonb, null),
  ('b343e13d-f1d2-56eb-ac0c-a154a66beabc'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 29, 'Bloco 5 — Problemas integradores e raciocínio', 'Um terreno circular possui 20 m de diâmetro. Quantos metros de cerca são necessários? A R$ 18,00 por metro, qual o custo?', '[]'::jsonb, null),
  ('267415e9-8279-53bf-81b8-6ed729902ac2'::uuid, (select id from public.subjects where slug = 'matematica-dia-2'), 30, 'Bloco 5 — Problemas integradores e raciocínio', 'Oito trabalhadores constroem um muro em 18 dias. Após 6 dias, mais 4 trabalhadores são contratados, com produtividade individual igual. Quantos dias, ao todo, serão necessários?', '[]'::jsonb, null),
  ('af3d01c3-1ed4-5955-b778-835e57588434'::uuid, (select id from public.subjects where slug = 'filosofia'), 1, 'Bloco 1 — Viver humanamente', 'O que significa viver humanamente? Explique quais características diferenciam a experiência humana de uma existência baseada apenas em necessidades biológicas.', '[]'::jsonb, null),
  ('af93d946-a4ad-5414-a003-09ba716fa5bb'::uuid, (select id from public.subjects where slug = 'filosofia'), 2, 'Bloco 1 — Viver humanamente', 'Por que a convivência com outras pessoas é importante para a formação de um indivíduo?', '[]'::jsonb, null),
  ('537fb952-26c2-5b06-938c-67d0f022d3b3'::uuid, (select id from public.subjects where slug = 'filosofia'), 3, 'Bloco 1 — Viver humanamente', 'Explique como cultura, educação e relações sociais influenciam a maneira como uma pessoa pensa e age.', '[]'::jsonb, null),
  ('d1c6d649-ad61-59d3-859e-0d558ab210f1'::uuid, (select id from public.subjects where slug = 'filosofia'), 4, 'Bloco 1 — Viver humanamente', 'Uma pessoa pode viver em sociedade sem respeitar os outros? Quais seriam as consequências para a coletividade?', '[]'::jsonb, null),
  ('c9ec82c5-07d6-5113-8893-64935fd8a8a4'::uuid, (select id from public.subjects where slug = 'filosofia'), 5, 'Bloco 2 — Respeito ao diferente', 'Explique o significado de respeitar as diferenças e por que isso é importante para uma sociedade.', '[]'::jsonb, null),
  ('fe9e5358-85d2-542c-a782-5e22d4767d82'::uuid, (select id from public.subjects where slug = 'filosofia'), 6, 'Bloco 2 — Respeito ao diferente', 'Qual é a diferença entre tolerar alguém e respeitar verdadeiramente suas diferenças?', '[]'::jsonb, null),
  ('320165b4-cf29-5ff4-9f77-cf4b0d6b4110'::uuid, (select id from public.subjects where slug = 'filosofia'), 7, 'Bloco 2 — Respeito ao diferente', 'Um aluno é excluído de um grupo por possuir opiniões diferentes. Analise a situação e apresente uma solução baseada no respeito.', '[]'::jsonb, null),
  ('79c65a5b-7f8d-58d0-9519-f86fd592f68d'::uuid, (select id from public.subjects where slug = 'filosofia'), 8, 'Bloco 2 — Respeito ao diferente', 'Por que reconhecer perspectivas diferentes não significa necessariamente concordar com elas?', '[]'::jsonb, null),
  ('9b0c2a09-40e4-5197-9f0e-2e0ceb0b73ae'::uuid, (select id from public.subjects where slug = 'filosofia'), 9, 'Bloco 3 — Liberdade de escolha', 'O que significa ter liberdade de escolha? Apresente um exemplo cotidiano.', '[]'::jsonb, null),
  ('78fb1264-7ce0-58a3-a87a-b2b7bf9d9769'::uuid, (select id from public.subjects where slug = 'filosofia'), 10, 'Bloco 3 — Liberdade de escolha', 'Toda escolha possui consequências? Explique a relação entre liberdade e responsabilidade.', '[]'::jsonb, null),
  ('1ac7a40d-b3ff-5170-b038-dbb3f748e601'::uuid, (select id from public.subjects where slug = 'filosofia'), 11, 'Bloco 3 — Liberdade de escolha', 'Um estudante decide não estudar para uma avaliação porque prefere jogar videogame. Essa decisão representa liberdade? Quais consequências deverá assumir?', '[]'::jsonb, null),
  ('025a13d0-87a2-5503-b441-aa8d85dd3804'::uuid, (select id from public.subjects where slug = 'filosofia'), 12, 'Bloco 3 — Liberdade de escolha', 'Existe diferença entre fazer tudo o que se deseja e agir livremente? Desenvolva.', '[]'::jsonb, null),
  ('cbb15d8f-f678-5656-8fbe-bc30c5d5661b'::uuid, (select id from public.subjects where slug = 'filosofia'), 13, 'Bloco 4 — Liberdade em Spinoza', 'Quem foi Spinoza e qual é sua relação com o tema da liberdade?', '[]'::jsonb, null),
  ('68cfac2b-8b61-5b11-9eae-1b6f2cebd676'::uuid, (select id from public.subjects where slug = 'filosofia'), 14, 'Bloco 4 — Liberdade em Spinoza', 'Explique por que, para Spinoza, ser livre não significa simplesmente fazer tudo aquilo que desejamos.', '[]'::jsonb, null),
  ('0a256b45-7a99-5add-a990-0c204c81455a'::uuid, (select id from public.subjects where slug = 'filosofia'), 15, 'Bloco 4 — Liberdade em Spinoza', 'Qual é a importância do conhecimento e da compreensão das causas de nossas ações para a conquista da liberdade segundo Spinoza?', '[]'::jsonb, null),
  ('f0225654-12c5-5909-b702-fb61138cb85e'::uuid, (select id from public.subjects where slug = 'filosofia'), 16, 'Bloco 4 — Liberdade em Spinoza', 'Uma pessoa reage agressivamente porque não consegue controlar suas emoções. Como a reflexão sobre suas ações poderia ajudá-la?', '[]'::jsonb, null),
  ('24c89c2d-a5ac-5fdf-88ca-29b03ca2582d'::uuid, (select id from public.subjects where slug = 'filosofia'), 17, 'Bloco 5 — Mito da Caverna de Platão', 'Descreva a situação dos prisioneiros dentro da caverna apresentada por Platão.', '[]'::jsonb, null),
  ('4027a337-a713-5aa9-a718-83b96ee8bf6c'::uuid, (select id from public.subjects where slug = 'filosofia'), 18, 'Bloco 5 — Mito da Caverna de Platão', 'O que representam as sombras projetadas na parede da caverna?', '[]'::jsonb, null),
  ('6ddb0ccd-15a6-56e9-967b-88b5c409d8c6'::uuid, (select id from public.subjects where slug = 'filosofia'), 19, 'Bloco 5 — Mito da Caverna de Platão', 'Por que o prisioneiro que sai da caverna inicialmente sente dificuldade para enxergar o exterior? O que isso simboliza?', '[]'::jsonb, null),
  ('1e9a0895-761a-5318-a1d3-48849606ff9f'::uuid, (select id from public.subjects where slug = 'filosofia'), 20, 'Bloco 5 — Mito da Caverna de Platão', 'Uma pessoa acredita em tudo o que vê na internet sem questionar. Relacione a situação ao Mito da Caverna e explique como o conhecimento ajuda.', '[]'::jsonb, null)
on conflict (subject_id, number) do update set
