insert into public.question_answer_keys (question_id, answer_key, explanation)
select q.id, v.answer_key, v.explanation
from (values
  ('ingles', 1, 'Skimming: leitura rápida para captar a ideia geral; Scanning: busca rápida de informação específica.', 'Exemplo: Skimming para descobrir o tema de uma notícia; Scanning para localizar uma data ou um nome.'),
  ('ingles', 2, 'O texto descreve a rotina diária de Lucas.', null),
  ('ingles', 3, '(a) At 6:30 a.m.', '(b) At 7:15 a.m. (c) He plays soccer with his friends.'),
  ('ingles', 4, 'Scanning, pois a tarefa é localizar uma informação específica: a data.', null),
  ('ingles', 5, 'Skimming, porque permite identificar rapidamente o tema e a ideia geral.', null),
  ('ingles', 6, 'Fact é um fato/informação verificável.', 'Fake News é conteúdo falso ou enganoso apresentado como notícia. A diferença central é a correspondência com evidências verificáveis.'),
  ('ingles', 7, 'Não compartilhar; procurar a informação em canais oficiais da escola/órgãos responsáveis; comparar com fontes jornalísticas confiáveis e verificar data, autoria e evidências.', null),
  ('ingles', 8, 'Autoria identificada; instituição/editora responsável; data e contexto; referências/evidências verificáveis.', 'Também é válido citar transparência e confirmação por outras fontes.'),
  ('ingles', 9, 'Porque o título pode ser sensacionalista e a informação não está comprovada; compartilhar pode espalhar desinformação e causar danos.', null),
  ('ingles', 10, 'A comparação ajuda a confirmar dados, identificar divergências, vieses ou erros e verificar se há evidências independentes.', null),
  ('ingles', 11, 'Bullying é agressão/intimidação repetida em contexto presencial ou social; cyberbullying ocorre por meios digitais.', 'Ex.: apelidos humilhantes repetidos na escola; mensagens ofensivas ou exposição vexatória em rede social.'),
  ('ingles', 12, 'É uma forma de cyberbullying/violência digital e pode violar privacidade e dignidade, causar sofrimento e ampliar a humilhação pela circulação online.', null),
  ('ingles', 13, 'Sofrimento emocional, medo/ansiedade, isolamento, queda no rendimento escolar, baixa autoestima ou dificuldade de convivência.', null),
  ('ingles', 14, 'Não reforçar nem compartilhar; apoiar a vítima; guardar evidências sem redistribuí-las; denunciar/bloquear e comunicar um adulto responsável ou a escola.', null),
  ('ingles', 15, 'Porque ações digitais também afetam pessoas reais, deixam registros e podem violar regras e leis; anonimato não elimina consequências.', null),
  ('ingles', 16, 'Regras organizam a convivência, protegem direitos e definem responsabilidades.', 'Exemplos: colaborar nas tarefas domésticas; respeitar horários e colegas na escola; obedecer às leis de trânsito.'),
  ('ingles', 17, '(a) Os estudantes devem respeitar seus professores.', '(b) Devemos seguir as regras da escola. (c) As pessoas deveriam/se devem respeitar umas às outras. Must expressa obrigação; should expressa recomendação/dever.'),
  ('ingles', 18, 'Audience é o público/leitor a quem o texto se dirige; Purpose é o objetivo comunicativo do texto, como informar, explicar ou convencer.', null),
  ('ingles', 19, 'Audience: colegas/alunos.', 'Purpose: convencer a preservar a escola. Main idea: todos devem cuidar do espaço escolar. Argumentos: ambiente limpo favorece saúde/aprendizagem; conservar materiais reduz desperdício e beneficia todos.'),
  ('ingles', 20, 'Resposta pessoal.', 'Espera-se parágrafo coerente em inglês, com ideia principal, pelo menos dois apoios e conclusão. Exemplo: “Respect is important at school. Students should listen to each other. We must respect teachers and classmates. Respect helps everyone feel safe and welcome. A respectful school is better for learning.”'),
  ('portugues', 1, 'São recursos expressivos que exploram sentidos e formas de expressão para produzir efeitos como intensidade, emoção, humor, imagem ou ênfase.', null),
  ('portugues', 2, 'Metáfora: o coração é associado a um deserto para sugerir vazio, solidão ou tristeza, sem usar conectivo comparativo.', null),
  ('portugues', 3, 'Comparação, marcada pelo conectivo “como”; aproxima o brilho dos olhos ao das estrelas.', null),
  ('portugues', 4, 'Personificação/prosopopeia: atribui ao vento uma ação humana, sussurrar.', null),
  ('portugues', 5, 'Comparação aproxima elementos explicitamente, geralmente com “como”, “tal qual” etc.', 'Metáfora faz associação implícita. Exemplos: “forte como um leão”; “ele é um leão”.'),
  ('portugues', 6, 'Hipérbole: exagero intencional para enfatizar que a informação foi repetida muitas vezes.', null),
  ('portugues', 7, 'Hipérbole: exagero para expressar muita fome; não significa morte literal.', null),
  ('portugues', 8, 'Sinestesia: mistura sensações de sentidos diferentes, associando “doce” (paladar) a “som” (audição).', null),
  ('portugues', 9, 'Resposta pessoal.', 'Verificar: metáfora implícita; comparação explícita; atribuição de ação/característica humana a ser não humano; exagero intencional.'),
  ('portugues', 10, 'Personificação: atribui à cidade a ação/sentimento de acordar triste; cria atmosfera de tristeza.', null),
  ('portugues', 11, 'Palavra invariável que modifica verbo, adjetivo ou outro advérbio, acrescentando circunstância ou intensidade, como tempo, lugar, modo, negação e dúvida.', null),
  ('portugues', 12, '(a) cedo — tempo; (b) longe — lugar; (c) talvez — dúvida; amanhã — tempo; (d) calmamente — modo; (e) não — negação.', null),
  ('portugues', 13, '(a) ontem — tempo; (b) rapidamente — modo; (c) aqui — lugar; (d) talvez — dúvida; (e) muito — intensidade.', null),
  ('portugues', 14, 'Tempo indica quando (ontem, cedo); lugar indica onde (aqui, longe); modo indica como (bem, calmamente); intensidade indica grau (muito, bastante).', null),
  ('portugues', 15, '“Bastante” é advérbio de intensidade: intensifica a ação de estudar.', null),
  ('portugues', 16, '(a) educadamente; (b) rapidamente; (c) atentamente; (d) claramente.', null),
  ('portugues', 17, 'Em (a), “muito” é advérbio de intensidade, modifica “inteligente” e é invariável.', 'Em (b), “muitos” acompanha “livros”, funciona como pronome indefinido/adjetivo indefinido conforme a classificação adotada no material escolar, concordando em gênero e número.'),
  ('portugues', 18, 'Resposta pessoal.', 'Verificar cinco advérbios corretamente identificados e classificados, preferencialmente de circunstâncias distintas.'),
  ('portugues', 19, 'Ontem — tempo; muito — intensidade; cedo — tempo; rapidamente — modo; talvez — dúvida.', 'A expressão “antes do intervalo” é locução temporal e não deve ser classificada como advérbio.'),
  ('portugues', 20, 'Resposta pessoal.', 'Verificar parágrafo coerente, pelo menos quatro advérbios corretamente empregados e duas figuras de linguagem identificadas e justificadas.'),
  ('matematica-dia-1', 1, 'Razão é a comparação entre duas quantidades por meio de uma divisão.', 'Pode ser escrita como a:b ou a/b, com atenção às unidades e à ordem.'),
  ('matematica-dia-1', 2, '(a) 12/18 = 2/3; (b) 18/12 = 3/2; (c) 12/30 = 2/5.', null),
  ('matematica-dia-1', 3, '(a) 2:3; (b) 4:7; (c) 3:4.', null),
  ('matematica-dia-1', 4, 'Razão 2:3.', 'Como 9 é 3 vezes 3, leite = 2 × 3 = 6 xícaras.'),
  ('matematica-dia-1', 5, 'Proporção é igualdade entre duas razões.', 'Pode-se verificar por simplificação ou pelo produto dos extremos igual ao produto dos meios.'),
  ('matematica-dia-1', 6, 'Sim.', '8/12 simplifica para 2/3; também 2×12 = 3×8 = 24.'),
  ('matematica-dia-1', 7, '3×20 = 5x; 60 = 5x; x = 12.', null),
  ('matematica-dia-1', 8, 'Fator de ampliação = 30/10 = 3.', 'Altura = 15×3 = 45 cm.'),
  ('matematica-dia-1', 9, 'Diretamente proporcionais: variam no mesmo sentido e mantêm a razão constante.', 'Inversamente proporcionais: quando uma aumenta, a outra diminui, mantendo constante o produto, nas condições do problema.'),
  ('matematica-dia-1', 10, 'Preço unitário = 24/3 = R$ 8,00.', 'Total = 7×8 = R$ 56,00.'),
  ('matematica-dia-1', 11, 'Velocidade = 120/2 = 60 km/h.', 'Em 5 h: 60×5 = 300 km.'),
  ('matematica-dia-1', 12, 'Inversamente proporcional: 4×12 = 8×d; d = 48/8 = 6 dias.', null),
  ('matematica-dia-1', 13, 'Circunferência é a linha curva fechada cujos pontos estão à mesma distância do centro; círculo é a região plana delimitada por essa circunferência.', null),
  ('matematica-dia-1', 14, 'Diâmetro = 2×5 = 10 cm.', 'Comprimento = 2πr = 2×3,14×5 = 31,4 cm.'),
  ('matematica-dia-1', 15, 'Comprimento = πd = 3,14×70 = 219,8 cm.', null),
  ('matematica-dia-2', 1, 'Meninos = 240−144 = 96.', 'Razão 144:96 = 3:2.'),
  ('matematica-dia-2', 2, '180/3 = 60 peças/h.', 'Em 8 h: 480 peças.'),
  ('matematica-dia-2', 3, '50/2 = 25 km por cm.', '7,5×25 = 187,5 km.'),
  ('matematica-dia-2', 4, 'Total de partes = 7; fator = 35/7 = 5.', 'Azul = 20 partes; branca = 15 partes.'),
  ('matematica-dia-2', 5, '9x = 7×45 = 315; x = 35.', null),
  ('matematica-dia-2', 6, 'Consumo = 180/15 = 12 km/L.', 'Litros = 300/12 = 25 L.'),
  ('matematica-dia-2', 7, 'Total de partes = 20; fator = 50/20 = 2,5.', 'Meninos = 8×2,5 = 20; meninas = 12×2,5 = 30.'),
  ('matematica-dia-2', 8, '300/4 = 75 g por pessoa; 75×10 = 750 g.', null),
  ('matematica-dia-2', 9, '240/4 = 60 peças/h; 60×9 = 540 peças.', null),
  ('matematica-dia-2', 10, '175/5 = R$ 35 por ingresso; 12×35 = R$ 420,00.', null),
  ('matematica-dia-2', 11, '180/6 = R$ 30/h; 9×30 = R$ 270,00.', null),
  ('matematica-dia-2', 12, '18/3 = 6 L/min; 6×11 = 66 litros.', null),
  ('matematica-dia-2', 13, '6×15 = 10×d; d = 90/10 = 9 dias.', null),
  ('matematica-dia-2', 14, 'Distância = 4×60 = 240 km.', 'Tempo = 240/80 = 3 horas.'),
  ('matematica-dia-2', 15, '12×20 = 15×d; d = 240/15 = 16 dias.', null),
  ('matematica-dia-2', 16, '3×12 = 4×t; t = 36/4 = 9 horas.', null),
  ('matematica-dia-2', 17, 'Porque mais trabalhadores dividem o mesmo serviço; se a produtividade individual for igual, aumenta a taxa conjunta de execução e o tempo diminui, mas o trabalho total permanece.', null),
  ('matematica-dia-2', 18, 'O diâmetro corresponde a dois raios: d = 2r; portanto r = d/2.', null),
  ('matematica-dia-2', 19, 'd = 16 cm; C = 2×3,14×8 = 50,24 cm.', null),
  ('matematica-dia-2', 20, 'C = πd = 3,14×20 = 62,8 cm.', null),
  ('matematica-dia-2', 21, 'C = 2×3,14×35 = 219,8 cm por volta.', 'Em 10 voltas: 2.198 cm = 21,98 m.'),
  ('matematica-dia-2', 22, 'C = 2πr; 62,8 = 6,28r; r = 10 cm.', null),
  ('matematica-dia-2', 23, 'C1 = 2×3,14×4 = 25,12 cm.', 'C2 = 2×3,14×8 = 50,24 cm. A segunda tem o dobro do comprimento.'),
  ('matematica-dia-2', 24, 'Uma volta = 3,14×100 = 314 m.', 'Três voltas = 942 m.'),
  ('matematica-dia-2', 25, 'Produção por máquina-hora = 600/(5×4) = 30.', 'Total = 30×8×6 = 1.440 peças.'),
