  ('filosofia', 1, 'Resposta argumentativa: envolve linguagem, cultura, consciência, relações, valores, reflexão, criação e responsabilidade, além das necessidades biológicas.', null),
  ('filosofia', 2, 'Porque aprendemos linguagem, valores, regras, conhecimentos e modos de agir nas relações; a identidade também se forma socialmente.', null),
  ('filosofia', 3, 'Elas transmitem conhecimentos, valores, hábitos e perspectivas; influenciam, mas não determinam totalmente, pois o indivíduo pode refletir e questionar.', null),
  ('filosofia', 4, 'Pode agir assim, mas isso prejudica confiança, segurança, direitos e cooperação, podendo gerar conflitos e exclusão.', null),
  ('filosofia', 5, 'Reconhecer a dignidade e os direitos das pessoas, mesmo com diferenças de opinião, cultura, aparência ou modo de vida; favorece igualdade e convivência.', null),
  ('filosofia', 6, 'Tolerar pode significar apenas suportar; respeitar implica reconhecer dignidade, direitos e ouvir sem discriminar.', null),
  ('filosofia', 7, 'Identificar exclusão/preconceito; propor diálogo, escuta, regras inclusivas, participação e intervenção responsável de colegas/adultos.', null),
  ('filosofia', 8, 'É possível ouvir e reconhecer o direito do outro à opinião, mantendo discordância e argumentando sem desrespeitar.', null),
  ('filosofia', 9, 'Poder avaliar alternativas e decidir entre elas dentro das condições e limites existentes; exemplo: escolher como organizar o tempo de estudo.', null),
  ('filosofia', 10, 'Escolhas normalmente produzem consequências; responsabilidade é reconhecer e responder pelos efeitos das próprias decisões.', null),
  ('filosofia', 11, 'É uma escolha possível, mas não elimina consequências, como menor preparação e possível resultado ruim; liberdade envolve assumir responsabilidade.', null),
  ('filosofia', 12, 'Sim.', 'Fazer qualquer desejo sem reflexão pode ser impulsivo e prejudicar outros; liberdade consciente considera razões, consequências e limites.'),
  ('filosofia', 13, 'Baruch/Benedictus de Spinoza foi filósofo do século XVII.', 'Sua filosofia relaciona liberdade ao conhecimento da necessidade, das causas e à ação guiada pela razão.'),
  ('filosofia', 14, 'Desejos podem ser determinados por causas que desconhecemos e por paixões.', 'A liberdade aumenta quando compreendemos essas causas e agimos com mais razão.'),
  ('filosofia', 15, 'Conhecer causas reduz a submissão a paixões e ideias inadequadas, permitindo agir com maior compreensão e autonomia racional.', null),
  ('filosofia', 16, 'Reconhecer causas e gatilhos, compreender emoções, avaliar consequências e escolher resposta mais racional, em vez de agir automaticamente.', null),
  ('filosofia', 17, 'Prisioneiros acorrentados desde sempre, voltados para uma parede, veem sombras projetadas e as tomam como realidade.', null),
  ('filosofia', 18, 'Aparências, opiniões e conhecimento limitado, confundidos com a realidade.', null),
  ('filosofia', 19, 'Os olhos precisam se adaptar à luz; simboliza o esforço e o desconforto de abandonar crenças e avançar para o conhecimento.', null),
  ('filosofia', 20, 'Pode estar presa a aparências/sombras.', 'Questionar, verificar fontes, buscar evidências e comparar perspectivas representa o caminho de saída da ignorância para uma compreensão mais fundamentada.')
) as v(subject_slug, question_number, answer_key, explanation)
join public.subjects s on s.slug = v.subject_slug
join public.questions q on q.subject_id = s.id and q.number = v.question_number
on conflict (question_id) do update set
  answer_key = excluded.answer_key,
  explanation = excluded.explanation;
